/** COMPLETE_RECEIPT with its command line rewritten (a replacement function keeps every $ in the line literal). */
const commandLine = (line: string): string => COMPLETE_RECEIPT.replace(`\`${FIXTURE_COMMAND}\` -> exit 0`, () => line);
/** Every printable ASCII character but the hyphen (N27: one of them after the run that follows the command). */
const PRINTABLE_NOT_HYPHEN: readonly string[] = Array.from({ length: 0x7e - 0x21 + 1 }, (_, offset) => String.fromCodePoint(0x21 + offset)).filter(character => character !== "-");
/** The runs of spaces or tabs N27 sets between the command and its arrow. */
